"""Integration tests verifying Browser SDK payloads and end-to-end collection."""

import uuid
from datetime import datetime, timezone
import pytest
from httpx import AsyncClient
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from api.app.models.event import Event
from api.app.models.session import Session
from api.app.models.user import User


@pytest.mark.asyncio
async def test_sdk_batch_beacon_payload_ingestion(
    client: AsyncClient,
    superadmin_user: User,
    db_session: AsyncSession,
):
    """Verify that a batch payload generated by the browser SDK transports and persists cleanly."""
    login_resp = await client.post(
        "/api/v1/auth/google",
        json={"id_token": f"mock_google_id_token:{superadmin_user.email}:sub_admin_123"},
    )
    auth_headers = {"Authorization": f"Bearer {login_resp.json()['access_token']}"}

    key_resp = await client.post(
        "/api/v1/apps/askanna/keys",
        json={"environment": "live", "name": "SDK Integration Test Key"},
        headers=auth_headers,
    )
    raw_key = key_resp.json()["raw_key"]

    # Emulate payload queued by Browser SDK with 3-tier consent and sanitized fields
    session_id = f"ses_{uuid.uuid4().hex[:16]}"
    visitor_id = str(uuid.uuid4())
    event_1_id = uuid.uuid4()
    event_2_id = uuid.uuid4()

    sdk_payload = {
        "write_key": raw_key,
        "batch": [
            {
                "event_id": str(event_1_id),
                "event_type": "pageview",
                "event_name": "page_view",
                "visitor_id": visitor_id,
                "session_id": session_id,
                "page_path": "/app/analytics?tab=overview&token=[REDACTED]",
                "referrer": "https://askanna.ai",
                "duration_ms": 120,
                "metadata": {"is_returning": False, "device_type": "desktop"},
                "timestamp": datetime.now(timezone.utc).isoformat(),
            },
            {
                "event_id": str(event_2_id),
                "event_type": "click",
                "event_name": "export_report_button",
                "visitor_id": visitor_id,
                "session_id": session_id,
                "page_path": "/app/analytics",
                "referrer": "https://askanna.ai",
                "duration_ms": 45,
                "metadata": {"button_id": "csv_export", "format": "csv"},
                "timestamp": datetime.now(timezone.utc).isoformat(),
            },
        ],
    }

    # Transmit via sendBeacon style with query param key
    resp = await client.post(
        f"/v1/batch?key={raw_key}",
        json=sdk_payload,
        headers={"Origin": "https://askanna.ai"},
    )
    assert resp.status_code == 202
    assert resp.json()["processed_count"] == 2

    # Verify both events persisted in Firestore
    e1_snap = db_session.db.events_col("askanna", "live").document(str(event_1_id)).get()
    e2_snap = db_session.db.events_col("askanna", "live").document(str(event_2_id)).get()
    assert e1_snap.exists
    assert e2_snap.exists

    # Verify session persisted with 2 touches
    sess_snap = db_session.db.sessions_col("askanna", "live").document(session_id).get()
    assert sess_snap.exists
    sess = Session(**sess_snap.to_dict())
    assert sess is not None
    assert sess.app_id == "askanna"
    assert sess.visitor_id == visitor_id
    assert sess.pageviews_count >= 1
